// Exercise sci::min<T> with a few concrete instantiations and assert key properties.
// No persistent inputs or API-managed outputs are involved; pure value function.
{
    // T = int
    int x = (int)*FUZZ_PARAM(int);
    // Create y close to x to hit equal/less/greater branches
    int delta = (int)((*FUZZ_PARAM(unsigned int)) % 3) - 1; // {-1,0,1}
    int y = x + delta;
    int r = sci::min<int>(x, y);
    FUZZ_ASSERT((r == x) || (r == y), "min<int> result must equal one of the inputs");
    FUZZ_ASSERT((r <= x) && (r <= y), "min<int> must be <= both inputs");

    // T = size_t (covers unsigned path)
    size_t ux = (size_t)*FUZZ_PARAM(size_t);
    size_t uy = (size_t)*FUZZ_PARAM(size_t);
    size_t ur = sci::min<size_t>(ux, uy);
    FUZZ_ASSERT((ur == ux) || (ur == uy), "min<size_t> result must equal one of the inputs");
    FUZZ_ASSERT((ur <= ux) && (ur <= uy), "min<size_t> must be <= both inputs");

    // T = ptrdiff_t (Sci_Position underlying)
    ptrdiff_t px = (ptrdiff_t)*FUZZ_PARAM(ptrdiff_t);
    ptrdiff_t py = (ptrdiff_t)*FUZZ_PARAM(ptrdiff_t);
    ptrdiff_t pr = sci::min<ptrdiff_t>(px, py);
    FUZZ_ASSERT((pr == px) || (pr == py), "min<ptrdiff_t> result must equal one of the inputs");
    FUZZ_ASSERT((pr <= px) && (pr <= py), "min<ptrdiff_t> must be <= both inputs");

    // Validation summary: Assertions enforce correctness; no resources to manage.
}

// Exercise sci::max<T> with multiple instantiations and assert key properties.
{
    // T = int
    int x = (int)*FUZZ_PARAM(int);
    int delta = (int)((*FUZZ_PARAM(unsigned int)) % 3) - 1; // {-1,0,1}
    int y = x + delta;
    int r = sci::max<int>(x, y);
    FUZZ_ASSERT((r == x) || (r == y), "max<int> result must equal one of the inputs");
    FUZZ_ASSERT((r >= x) && (r >= y), "max<int> must be >= both inputs");

    // T = size_t
    size_t ux = (size_t)*FUZZ_PARAM(size_t);
    size_t uy = (size_t)*FUZZ_PARAM(size_t);
    size_t ur = sci::max<size_t>(ux, uy);
    FUZZ_ASSERT((ur == ux) || (ur == uy), "max<size_t> result must equal one of the inputs");
    FUZZ_ASSERT((ur >= ux) && (ur >= uy), "max<size_t> must be >= both inputs");

    // T = ptrdiff_t
    ptrdiff_t px = (ptrdiff_t)*FUZZ_PARAM(ptrdiff_t);
    ptrdiff_t py = (ptrdiff_t)*FUZZ_PARAM(ptrdiff_t);
    ptrdiff_t pr = sci::max<ptrdiff_t>(px, py);
    FUZZ_ASSERT((pr == px) || (pr == py), "max<ptrdiff_t> result must equal one of the inputs");
    FUZZ_ASSERT((pr >= px) && (pr >= py), "max<ptrdiff_t> must be >= both inputs");

    // Validation summary: Assertions ensure result meets spec; no side effects or ownership concerns.
}

// Exercise sci::clamp<T>, enforcing lower <= upper and asserting contract properties.
{
    // T = int for clear ordering behavior
    int x = (int)*FUZZ_PARAM(int);
    int lower = (int)*FUZZ_PARAM(int);
    int upper = (int)*FUZZ_PARAM(int);

    // Ensure valid interval as required by the function contract: lower <= upper
    if (lower > upper) {
        int tmp = lower; lower = upper; upper = tmp;
    }

    int r = sci::clamp<int>(x, lower, upper);

    // Core clamp properties
    FUZZ_ASSERT(r >= lower, "clamp<int> result must be >= lower bound");
    FUZZ_ASSERT(r <= upper, "clamp<int> result must be <= upper bound");

    // Boundary behaviors
    if (x < lower) {
        FUZZ_ASSERT(r == lower, "clamp<int> must return lower when x < lower");
    } else if (x > upper) {
        FUZZ_ASSERT(r == upper, "clamp<int> must return upper when x > upper");
    } else {
        FUZZ_ASSERT(r == x, "clamp<int> must return x when lower <= x <= upper");
    }

    // Also test an unsigned instantiation
    size_t ux = (size_t)*FUZZ_PARAM(size_t);
    size_t ul = (size_t)*FUZZ_PARAM(size_t);
    size_t uu = (size_t)*FUZZ_PARAM(size_t);
    if (ul > uu) { size_t t = ul; ul = uu; uu = t; }
    size_t ur = sci::clamp<size_t>(ux, ul, uu);
    FUZZ_ASSERT(ur >= ul && ur <= uu, "clamp<size_t> result must be within [lower, upper]");

    // Validation summary: Interval normalization enforces precondition; assertions cover all paths.
}

// Exercise bit-shift by MarkerOutline enumerator while avoiding UB on signed left-shifts.
// Constraint enforcement:
// - Use i == 0 so that any left shift remains defined and equals 0.
// - Choose a valid MarkerOutline enumerator from the known set.
int i = 0; // prevents signed left-shift overflow UB for any shift amount
// Pick a valid MarkerOutline value deterministically from fuzz data
