// Construct a concrete IDocument with a small in-memory buffer and simple logic.
class MockDocument final : public Scintilla::IDocument {
    std::string data_;
    std::string styles_; // byte-per-position style storage
    enum { kMaxLines = 512 }; // use enum to allow constant in local class
    int lineState_[kMaxLines];
    int lineLevel_[kMaxLines];
    int codePage_ = 65001; // UTF-8

    static Sci_Line CountLines(const std::string &s) noexcept {
        Sci_Line lines = 1;
        for (size_t i = 0; i < s.size(); ++i) if (s[i] == '\n') ++lines;
        return lines;
    }
    static Sci_Line LineFromPos(const std::string &s, Sci_Position pos) noexcept {
        if (pos <= 0) return 0;
        if (pos > static_cast<Sci_Position>(s.size())) pos = static_cast<Sci_Position>(s.size());
        Sci_Line line = 0;
        for (Sci_Position i = 0; i < pos; ++i) if (s[(size_t)i] == '\n') ++line;
        return line;
    }
    static Sci_Position LineStartPos(const std::string &s, Sci_Line line) noexcept {
        if (line <= 0) return 0;
        Sci_Line cur = 0;
        for (size_t i = 0; i < s.size(); ++i) {
            if (cur == line) return static_cast<Sci_Position>(i);
            if (s[i] == '\n') ++cur;
        }
        return static_cast<Sci_Position>(s.size());
    }
public:
    explicit MockDocument(std::string s) : data_(std::move(s)), styles_(data_.size(), '\0') {
        for (int i = 0; i < kMaxLines; ++i) { lineState_[i] = 0; lineLevel_[i] = 0; }
    }
    int SCI_METHOD Version() const noexcept override { return 2; }
    void SCI_METHOD SetErrorStatus(int) noexcept override { /* ignore */ }
    Sci_Position SCI_METHOD Length() const noexcept override { return static_cast<Sci_Position>(data_.size()); }
    void SCI_METHOD GetCharRange(char *buffer, Sci_Position position, Sci_Position lengthRetrieve) const noexcept override {
        if (!buffer || position < 0 || lengthRetrieve < 0) return;
        size_t pos = static_cast<size_t>(position);
        size_t len = static_cast<size_t>(lengthRetrieve);
        if (pos > data_.size()) return;
        size_t avail = data_.size() - pos;
        if (len > avail) len = avail;
        for (size_t i = 0; i < len; ++i) buffer[i] = data_[pos + i];
    }
    unsigned char SCI_METHOD StyleAt(Sci_Position position) const noexcept override {
        if (position < 0 || (size_t)position >= styles_.size()) return 0;
        return static_cast<unsigned char>(styles_[(size_t)position]);
    }
    Sci_Line SCI_METHOD LineFromPosition(Sci_Position position) const noexcept override {
        return LineFromPos(data_, position);
    }
    Sci_Position SCI_METHOD LineStart(Sci_Line line) const noexcept override {
        return LineStartPos(data_, line);
    }
    int SCI_METHOD GetLevel(Sci_Line line) const noexcept override {
        if (line < 0) return 0;
        Sci_Line lc = CountLines(data_);
        if (line >= lc) return 0;
        int idx = (line < kMaxLines) ? (int)line : (kMaxLines - 1);
        return lineLevel_[idx];
    }
    int SCI_METHOD SetLevel(Sci_Line line, int level) override {
        Sci_Line lc = CountLines(data_);
        if (line < 0 || line >= lc) return 0;
        int idx = (line < kMaxLines) ? (int)line : (kMaxLines - 1);
        lineLevel_[idx] = level;
        return 1;
    }
    int SCI_METHOD GetLineState(Sci_Line line) const noexcept override {
        Sci_Line lc = CountLines(data_);
        if (line < 0 || line >= lc) return 0;
        int idx = (line < kMaxLines) ? (int)line : (kMaxLines - 1);
        return lineState_[idx];
    }
    int SCI_METHOD SetLineState(Sci_Line line, int state) override {
        Sci_Line lc = CountLines(data_);
        if (line < 0 || line >= lc) return 0;
        int idx = (line < kMaxLines) ? (int)line : (kMaxLines - 1);
        lineState_[idx] = state;
        return 1;
    }
    void SCI_METHOD StartStyling(Sci_Position) noexcept override { /* no-op baseline */ }
    bool SCI_METHOD SetStyleFor(Sci_Position length, unsigned char style) override {
        if (length < 0) return false;
        size_t len = static_cast<size_t>(length);
        if (len == 0 || styles_.empty()) return true;
        if (len > styles_.size()) len = styles_.size();
        for (size_t i = 0; i < len; ++i) styles_[i] = static_cast<char>(style);
        return true;
    }
    bool SCI_METHOD SetStyles(Sci_Position length, const unsigned char *styles) override {
        if (!styles || length < 0) return false;
        size_t len = static_cast<size_t>(length);
        if (len > styles_.size()) len = styles_.size();
        for (size_t i = 0; i < len; ++i) styles_[i] = static_cast<char>(styles[i]);
        return true;
    }
    void SCI_METHOD DecorationSetCurrentIndicator(int) noexcept override { /* ignore */ }
    void SCI_METHOD DecorationFillRange(Sci_Position position, int, Sci_Position fillLength) override {
        if (position < 0 || fillLength <= 0) return;
        size_t pos = static_cast<size_t>(position);
        size_t len = static_cast<size_t>(fillLength);
        if (pos >= styles_.size()) return;
        size_t avail = styles_.size() - pos;
        if (len > avail) len = avail;
        for (size_t i = 0; i < len; ++i) styles_[pos + i] = static_cast<char>(styles_[pos + i] | (char)0x80);
    }
    void SCI_METHOD ChangeLexerState(Sci_Position, Sci_Position) override { /* no-op */ }
    int SCI_METHOD CodePage() const noexcept override { return codePage_; }
    bool SCI_METHOD IsDBCSLeadByte(unsigned char) const noexcept override { return false; }
    const char * SCI_METHOD BufferPointer() override { return data_.c_str(); }
    int SCI_METHOD GetLineIndentation(Sci_Line line) const noexcept override {
        Sci_Position start = LineStart(line);
        size_t i = (size_t)start;
        int indent = 0;
        while (i < data_.size()) {
            char c = data_[i];
            if (c == ' ') { ++indent; ++i; }
            else if (c == '\t') { indent += 4; ++i; }
            else break;
        }
        return indent;
    }
    Sci_Position SCI_METHOD LineEnd(Sci_Line line) const noexcept override {
        Sci_Position start = LineStart(line);
        for (size_t i = (size_t)start; i < data_.size(); ++i) if (data_[i] == '\n') return static_cast<Sci_Position>(i);
        return static_cast<Sci_Position>(data_.size());
    }
    Sci_Position SCI_METHOD GetRelativePosition(Sci_Position positionStart, Sci_Position characterOffset) const noexcept override {
        Sci_Position pos = positionStart + characterOffset;
        if (pos < 0) pos = 0;
        Sci_Position len = static_cast<Sci_Position>(data_.size());
        if (pos > len) pos = len;
        return pos;
    }
    int SCI_METHOD GetCharacterAndWidth(Sci_Position position, Sci_Position *pWidth) const noexcept override {
        if (pWidth) *pWidth = 1;
        if (position < 0 || (size_t)position >= data_.size()) return 0;
        return static_cast<unsigned char>(data_[(size_t)position]);
    }
    Scintilla::CharacterClass SCI_METHOD GetCharacterClass(unsigned int character) const noexcept override {
        if (character == (unsigned int)'\n' || character == (unsigned int)'\r') return Scintilla::CharacterClass::newLine;
        if (character == (unsigned int)' ' || character == (unsigned int)'\t') return Scintilla::CharacterClass::space;
        if ((character >= 'A' && character <= 'Z') || (character >= 'a' && character <= 'z') || (character >= '0' && character <= '9') || character == '_')
            return Scintilla::CharacterClass::word;
        if (character < 128u) return Scintilla::CharacterClass::punctuation;
        return Scintilla::CharacterClass::cjkWord;
    }
};

